// Actual WinForms fixture; no installed MMC or game interaction.
using System;using System.IO;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;using DynastyCOT.Collection;
class CollectionRepairWindowChecks {
 static int checks;static void Check(bool ok,string why){if(!ok)throw new IOException(why);checks++;}
 static object Field(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 static Task Invoke(object o,string name,params object[] args){return (Task)o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(o,args);}
 static void Image(Form form,string path){using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(path);}}
 [STAThread]static int Main(string[] args){try{
  string parent=Path.GetFullPath(args[0]),root=Path.Combine(parent,"MMC");Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,".cot-fixture"),"isolated");File.WriteAllText(Path.Combine(root,"MMCModManager.exe"),"fixture only");var fixture=new Fixture(root,parent);
  typeof(Ace.DynastyCOT.UserStorage).GetField("current",BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,new Ace.DynastyCOT.UserStore(Path.Combine(parent,"UserData")));
  DpiSupport.Initialize();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var catalog=CollectionProgram.Load();var latest=catalog.Modules.ToDictionary(m=>m.Id,m=>Json.Serializer().Deserialize<ModuleRelease>(Json.Serializer().Serialize(m.Current)));var btf=catalog.Get("BeyondTheField");btf.Current=Json.Serializer().Deserialize<ModuleRelease>(Json.Serializer().Serialize(btf.Current).Replace("1.0.25","1.0.24"));
  Directory.CreateDirectory(Path.Combine(root,"Plugins"));string archive=Path.Combine(args[1],latest[btf.Id].ArchiveName);using(var input=File.OpenRead(archive))using(var zip=new System.IO.Compression.ZipArchive(input)){using(var file=zip.GetEntry(btf.FileName).Open())using(var output=File.Create(Path.Combine(root,"Plugins",btf.FileName)))file.CopyTo(output);}
  var requests=new List<string>();bool offline=false;var download=new Downloads(fixture,(url,max)=>{lock(requests)requests.Add(url);if(offline)throw new IOException("offline fixture");var module=catalog.Modules.Single(m=>url.Contains(m.Repository));var r=latest[module.Id];if(url.EndsWith("/releases/latest"))return Json.Bytes(new{draft=false,prerelease=false,tag_name=r.Tag,html_url=r.PageUrl,body="Verified stable",assets=new object[]{new{name=r.ArchiveName,browser_download_url=r.ArchiveUrl,size=r.ArchiveBytes,digest="sha256:"+r.ArchiveSha256},new{name=module.Id+"-"+r.Version+"-verification.json"}}});return File.ReadAllBytes(Path.Combine(args[1],module.Id+"-"+r.Version+"-verification.json"));});
  Exception failure=null;using(var form=new CollectionForm(catalog,fixture)){form.ShowInTaskbar=false;typeof(CollectionForm).GetField("downloads",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(form,download);form.Shown+=async(s,e)=>{try{
   for(int i=0;!form.InspectionReady&&i<500;i++)await Task.Delay(10);Check(form.InspectionReady,"Fixture root ready");
   var targets=(Dictionary<string,ModuleRelease>)Field(form,"targets");var inventory=(Inventory)Field(form,"inventory");Check(VersionSelection.KeepNewer(inventory.Plugins.Single(p=>p.Module==btf.Id),targets[btf.Id],false),"Newer installed copy kept before automatic lookup");
   var watch=System.Diagnostics.Stopwatch.StartNew();await Invoke(form,"CheckVersions",false);double updateMs=watch.Elapsed.TotalMilliseconds;
   Check(targets[btf.Id].Version=="1.0.25","Verified hotfix becomes startup target despite older bundled catalog");Check(requests.Count==8&&requests.All(u=>!u.EndsWith(".zip")),"Four bounded metadata checks, zero module downloads");Check(((Label[])Field(form,"versions"))[0].Text.Contains("up to date"),"Installed hotfix correctly shown up to date");form.AuditLayout();Image(form,Path.Combine(parent,"main.png"));
   var explicitVersions=(HashSet<string>)Field(form,"explicitVersions");explicitVersions.Add(btf.Id);targets[btf.Id]=btf.Current;await Invoke(form,"CheckVersions",false);Check(targets[btf.Id].Version=="1.0.24","Explicit older selection survives refresh");explicitVersions.Clear();offline=true;await Invoke(form,"CheckVersions",false);Check(VersionSelection.KeepNewer(inventory.Plugins.Single(p=>p.Module==btf.Id),targets[btf.Id],false),"Offline refresh still keeps newer installed copy");
   using(var timer=new Timer{Interval=50}){timer.Tick+=(a,b)=>{foreach(Form dialog in Application.OpenForms.Cast<Form>().ToArray())if(dialog!=form&&dialog.Text=="Check & Repair"){Image(dialog,Path.Combine(parent,"repair-preview.png"));Check(dialog.Controls.Count>0,"Repair preview rendered");dialog.DialogResult=DialogResult.Cancel;dialog.Close();timer.Stop();}};timer.Start();await Invoke(form,"CheckRepair");}Check(Paths.HashFile(Path.Combine(root,"Plugins",btf.FileName))==latest[btf.Id].DllSha256,"Cancelling preview leaves exact installed fixture bytes");
   using(var icon=typeof(CollectionProgram).Assembly.GetManifestResourceStream("Collection.icon.ico"))using(var bytes=new MemoryStream()){icon.CopyTo(bytes);Check(Paths.Hash(bytes.ToArray())==Paths.HashFile(args[2]),"Exact new emblem icon embedded");}Check(form.Icon!=null,"Window uses embedded icon");File.WriteAllBytes(Path.Combine(parent,"window-results.json"),Json.Bytes(new{checks=checks,metadataRefreshMs=updateMs,zipDownloads=0,liveChanges=false}));
  }catch(Exception error){failure=error;}finally{form.Close();}};Application.Run(form);}if(failure!=null)throw failure;Console.WriteLine("PASS "+checks+" actual-window latest/default/offline/explicit-version/preview/icon checks. Fixture only.");return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
